# Important RCWs for a Washington patrol / SWAT officer.
# Official text: build-src/study_app/rcw_text/<cite>.txt, copied from app.leg.wa.gov on 2026-11-26 (statute text + history line).
# summary/points are study notes in our own words; quote must be an exact substring of the official text (checked at build).
VERIFIED = "Text checked against app.leg.wa.gov on 2026-11-26"
G_FORCE, G_TACT, G_ARREST, G_SEARCH, G_JUST, G_AUTH, G_CRIME, G_CERT, G_BH = (
  "Use of force", "Tactics & equipment", "Arrest", "Search & warrants", "Justifiable force (criminal code)",
  "Authority & duty to intervene", "Crimes against officers", "Certification", "Behavioral health")

RCW = [
 dict(cite="10.120.010", title="Use of force: definitions", group=G_FORCE,
  summary="Defines the words that control the statewide force standard: physical force, deadly force, necessary, de-escalation tactics, less lethal alternatives and totality of the circumstances.",
  points=["\"Necessary\" = no reasonably effective alternative appears to exist AND the force is reasonable and proportional to the lawful purpose or threat.",
          "\"Physical force\" excludes pat-downs, incidental touching, verbal commands and compliant handcuffing without pain or injury.",
          "\"Totality of the circumstances\" includes what happened leading up to the force, and the officer's own actions.",
          "De-escalation examples: clear instructions, slowing things down, distance/cover, one officer talking, calling crisis or backup resources."],
  quote="the type and amount of physical force or deadly force used is a reasonable and proportional response",
  cards=[("Under RCW 10.120.010, what two things make force \"necessary\"?","(1) Under the totality of the circumstances, a reasonably effective alternative to force does not appear to exist, and (2) the type and amount of force is a reasonable and proportional response to the lawful purpose or the threat."),
         ("Does RCW 10.120's \"physical force\" include compliant handcuffing?","No. Pat-downs, incidental touching, verbal commands and compliant handcuffing with no pain or injury are excluded.")]),
 dict(cite="10.120.020", title="Permissible uses of force", group=G_FORCE,
  summary="The statewide standard. Physical force only to the extent necessary for listed purposes (arrest, prevent escape, protect against a crime with probable cause, search warrant, stop flight from a lawful detention after notice, imminent threat of bodily injury, etc.). Deadly force only when necessary to protect against an immediate threat of serious physical injury or death. Officers must use reasonable care: de-escalate when possible, least force necessary, stop when necessity ends, less lethal before deadly when possible.",
  points=["Deadly force: \"immediate threat\" = objectively reasonable belief the person has present and apparent ability, opportunity and intent to immediately cause death or serious bodily injury.",
          "Reasonable care duties (3)(a)–(e): de-escalate when possible; least force necessary; consider characteristics (pregnancy, minor, vulnerable adult, impairment, suicidal, limited English, children present); stop when necessity ends; less lethal before deadly when possible; keep issued less lethal tools available.",
          "Force to stop someone fleeing a Terry detention is allowed only after they've been told they're detained and not free to leave.",
          "Tactics banned by policy or law may be used only to protect a life from an imminent threat.",
          "Agencies may adopt stricter rules (5)(d)."],
  quote="only when necessary to protect against an immediate threat of serious physical injury or death to the officer or another person",
  cards=[("When may a WA peace officer use deadly force under RCW 10.120.020(2)?","Only when necessary to protect against an immediate threat of serious physical injury or death to the officer or another person: an objectively reasonable belief the person has the present and apparent ability, opportunity and intent to immediately cause death or serious bodily injury."),
         ("List the reasonable-care duties in RCW 10.120.020(3).","When possible use available, appropriate de-escalation before physical force; use the least force necessary (considering the person's characteristics and conditions); stop force when necessity ends; when possible use less lethal alternatives before deadly force; keep issued less lethal alternatives reasonably available."),
         ("Can you use force to stop someone walking away from a Terry stop in WA?","Yes, if necessary, but only after the person has been given notice that they are being detained and are not free to leave (RCW 10.120.020(1)(i)).")]),
 dict(cite="10.120.030", title="AG model use-of-force and de-escalation policies", group=G_FORCE,
  summary="The Attorney General publishes model use-of-force and de-escalation policies. Every agency must adopt consistent policies or explain its departures to the AG, and must send the AG any later changes within 60 days.",
  points=["Model policies were due July 1, 2022; agency adoption or explanation by Dec 1, 2022.","Policy changes must be sent to the AG within 60 days.","The AG publishes a yearly status report."],
  quote="the attorney general shall develop and publish model policies on law enforcement's use of force and de-escalation tactics",
  cards=[("What must an agency do after changing its use-of-force policy (RCW 10.120.030)?","Send notice and copies of the relevant policies to the Attorney General within 60 days.")]),
 dict(cite="10.116.020", title="Chokehold or neck restraint prohibited", group=G_TACT,
  summary="Peace officers may not use a chokehold or any neck restraint (including vascular neck restraints). Agency policies must match.",
  points=["Chokehold = intentional direct pressure on the trachea/windpipe to restrict the airway.","Neck restraint = any vascular neck restraint or hold that presses the neck to constrict blood flow.","Only exception path is RCW 10.120.020(4): a banned tactic to protect a life from an imminent threat."],
  quote="A peace officer may not use a chokehold or neck restraint on another person in the course of his or her duties as a peace officer.",
  cards=[("Define \"neck restraint\" under RCW 10.116.020.","Any vascular neck restraint or similar restraint, hold or tactic in which pressure is applied to the neck to constrict blood flow. Banned for WA peace officers, along with chokeholds.")]),
 dict(cite="10.116.022", title="Hog-tying prohibited", group=G_TACT,
  summary="Officers may not hog-tie anyone or help put someone in a hog-tie (bound ankles fastened to bound wrists). Doing so counts as excessive force for the duty to intervene. Transport/waist chains and devices that don't fasten ankles to wrists are not covered.",
  points=["Added in 2024 (2024 c 291).","Hog-tying = excessive force under RCW 10.93.190, so witnessing officers must intervene and report."],
  quote="Hog-tying shall constitute the use of excessive force for the purposes of RCW  10.93.190.",
  cards=[("Is hog-tying allowed in WA? What else follows from it?","No (RCW 10.116.022). It is defined as excessive force for the duty to intervene (RCW 10.93.190), so other officers must intervene and report.")]),
 dict(cite="10.116.030", title="Use of tear gas", group=G_TACT,
  summary="Tear gas (CN, CS and similar airborne irritants, not OC) only when necessary to alleviate a present risk of serious harm from a riot, a barricaded subject or a hostage situation. Before using it: exhaust available alternatives, get supervisor authorization, announce, and allow time and space to comply. A riot outside a jail also needs the highest elected official (in a city, the mayor).",
  points=["Barricaded subject = focus of a police effort, in a place without immediate access, refusing orders to exit.","Hostage situation = person held against their will by an armed, potentially armed or otherwise dangerous suspect.","OC is excluded from the definition of tear gas."],
  quote="unless necessary to alleviate a present risk of serious harm posed by a: (a) Riot; (b) barricaded subject; or (c) hostage situation.",
  cards=[("Four steps before tear gas under RCW 10.116.030(2)?","(1) Exhaust available, appropriate alternatives; (2) get authorization from a supervising officer; (3) announce the intent to use tear gas; (4) allow sufficient time and space to comply."),
         ("Who must authorize tear gas for a riot in Federal Way (outside a jail)?","The highest elected official of the jurisdiction (for a city, the mayor), plus the normal 10.116.030(2) steps."),
         ("Is OC spray \"tear gas\" under RCW 10.116.030?","No. The definition covers CN, CS and similar airborne irritants and expressly excludes oleoresin capsicum (OC).")]),
 dict(cite="10.116.040", title="Military equipment", group=G_TACT,
  summary="Agencies may not acquire or use listed military equipment (e.g., .50 cal+ rifles, machine guns, armed vehicles/drones, explosive or incendiary grenades, LRADs, bayonets). Non-explosive stun, sting, smoke and tear-gas grenades and blast balls are not \"grenades\" under this section.",
  points=["Less-lethal launchers are not \"rifles\" under this section.","Federal surplus programs are still allowed for non-military items (medical, protective gear, unarmed vehicles, CEWs)."],
  quote="\"Grenade\" does not include other nonexplosive grenades designed to temporarily incapacitate or disorient subjects without causing permanent injury",
  cards=[("Are stun (flash-bang) grenades banned by RCW 10.116.040?","No. The ban covers explosive/incendiary grenades designed to injure or kill. Non-explosive grenades that temporarily incapacitate or disorient (stun, sting, smoke, tear gas, blast ball) are excluded from the definition.")]),
 dict(cite="10.116.050", title="Officers reasonably identifiable", group=G_TACT,
  summary="Agencies must make sure uniformed on-duty officers are reasonably identifiable: the uniform shows the officer's name or other information the public can see and the agency can use to identify the officer.",
  points=[],
  quote="the peace officer's uniform clearly displays the officer's name or other information that members of the public can see",
  cards=[("What does \"reasonably identifiable\" mean in RCW 10.116.050?","The uniform clearly displays the officer's name or other information the public can see and the agency can use to identify the officer.")]),
 dict(cite="10.116.060", title="Vehicular pursuit; shooting at moving vehicles", group=G_TACT,
  summary="As amended by Initiative 2113 (2024): pursue only with reasonable suspicion of a law violation, when the pursuit is necessary to identify or apprehend, the person poses a threat to others and the risk of not catching them outweighs the pursuit risk, with immediate supervisor notification and oversight. Pursuits that don't meet the rules must end. Firing at a moving vehicle only to stop an imminent threat of serious harm from the occupant's use of a deadly weapon; the vehicle itself counts only if used as a weapon and no other reasonable way to avoid harm exists.",
  points=["Requirements during a pursuit (2): follow agency rules on primary unit and number of cars; notify affected jurisdictions; direct communication (common radio channel); plan to end it with intervention options (PIT, spikes); EVOC, updated EVOC training in the previous two years where applicable, and certification in at least one intervention option.",
          "Jurisdictions with fewer than 15 commissioned officers may notify an on-call supervisor if none is on duty.",
          "\"Vehicular pursuit\" requires a uniformed officer in a car with lights and siren and a driver who appears aware and is willfully resisting."],
  quote="A vehicle pursuit not meeting the requirements under this section must be terminated.",
  cards=[("Four conditions to start a pursuit under RCW 10.116.060(1) (post-I-2113)?","(a) Reasonable suspicion the person violated the law; (b) pursuit necessary to identify or apprehend; (c) the person poses a threat to others and the risk of not apprehending outweighs the pursuit risk; (d) immediate supervisor notification and oversight, considering alternatives and safety factors (speed, weather, traffic, roads, minors in the car)."),
         ("When may you shoot at a moving vehicle under RCW 10.116.060(4)?","Only when necessary to protect against an imminent threat of serious physical harm from the operator's or a passenger's use of a deadly weapon. The vehicle is a deadly weapon only if the driver is using it as one and no other reasonable means to avoid the harm are immediately available.")]),
 dict(cite="10.31.040", title="Officer may break and enter; no-knock warrants barred", group=G_ARREST,
  summary="To make an arrest, an officer may break open doors or windows of a building if, after giving notice of office and purpose, admittance is refused. Since 2021, officers may not seek and courts may not issue a warrant with an exception to the knock-and-announce requirement.",
  points=["Washington has no no-knock warrants (2021 c 320).","Knock-and-announce case law (State v. Coyle; Wilson, Richards, Banks) still governs reasonableness and wait time."],
  quote="An officer may not seek and a court may not issue a search or arrest warrant granting an express exception to the requirement for the officer to provide notice of his or her office and purpose",
  cards=[("Can a WA judge issue a no-knock warrant?","No. RCW 10.31.040(2) bars officers from seeking and courts from issuing any search or arrest warrant with an express exception to giving notice of office and purpose."),
         ("Under RCW 10.31.040(1), when may an officer break a door to arrest?","After giving notice of his or her office and purpose and being refused admittance.")]),
 dict(cite="10.31.100", title="Arrest without warrant", group=G_ARREST,
  summary="Felony: arrest on probable cause. Misdemeanor or gross misdemeanor: only if committed in the officer's presence, unless an exception applies — e.g., offenses involving physical harm or threats, taking property, cannabis, minor in possession, or criminal trespass; listed traffic crimes (hit and run, reckless, DUI and others); indecent exposure; school weapons. Mandatory arrest for knowing violations of protection/no-contact orders and for domestic violence assault by someone 18+ within the past four hours.",
  points=["DV mandatory arrest (2)(d): 18+, assault on a family/household member or intimate partner within 4 hours, and the officer believes a felony assault, an assault causing bodily injury (visible or not), or an act meant to cause fear of imminent serious injury or death.",
          "Good-faith immunity for arrests under (2) and (9).",
          "(16): mandatory custody for DUI with a prior offense within 10 years (and other listed cases), unless hospitalized."],
  quote="A police officer may arrest a person without a warrant for committing a misdemeanor or gross misdemeanor only when the offense is committed in the presence of an officer",
  cards=[("General rule for warrantless misdemeanor arrests in WA?","Only when committed in the officer's presence, unless an RCW 10.31.100 exception applies (e.g., physical harm or threats, property taking, trespass, certain traffic crimes, DV order violations)."),
         ("When is a DV arrest mandatory under RCW 10.31.100(2)(d)?","Suspect is 18+, within the preceding four hours assaulted a family or household member or intimate partner, and the officer believes a felonious assault occurred, an assault caused bodily injury (observable or not), or an act was intended to cause reasonable fear of imminent serious bodily injury or death.")]),
 dict(cite="10.31.110", title="Alternatives to arrest: behavioral health", group=G_BH,
  summary="When someone with a known mental disorder or substance use disorder commits a crime, officers are authorized and encouraged to divert instead of arrest: take them to a crisis stabilization unit or 23-hour crisis relief center (12-hour hold, exam within 3 hours), refer to a designated crisis responder, release on agreement to outpatient treatment, or refer to mobile crisis or recovery navigator programs. Good-faith immunity.",
  points=["Officer is guided by local diversion guidelines.","Diversion agreements cannot require the person to stipulate to the facts."],
  quote="as an alternative to arrest, the arresting officer is authorized and encouraged to",
  cards=[("Name three diversion options under RCW 10.31.110.","Crisis stabilization unit or 23-hour crisis relief center (12-hour hold, exam within 3 hours); referral to a designated crisis responder; release on agreement to voluntary outpatient treatment; referral to mobile crisis or the regional diversion/recovery navigator program.")]),
 dict(cite="10.79.015", title="Search warrants: other grounds", group=G_SEARCH,
  summary="A magistrate who finds reasonable cause may issue a warrant to search for and seize evidence material to the investigation or prosecution of any homicide or felony (plus some older categories). Evidence held by news media generally requires a subpoena duces tecum unless the holder may be involved or the evidence would be destroyed or hidden.",
  points=["Day-to-day warrant mechanics are in CrR 2.3 / CrRLJ 2.3 (court rules), not summarized here."],
  quote="To search for and seize any evidence material to the investigation or prosecution of any homicide or any felony",
  cards=[("When does RCW 10.79.015(3) require a subpoena instead of a search warrant?","When the evidence is held by a radio/TV station, newspaper, magazine or wire service (or their employees), unless there's probable cause the holder may be involved in the crime or the evidence would be destroyed or hidden.")]),
 dict(cite="10.79.040", title="Search without warrant unlawful (dwellings)", group=G_SEARCH,
  summary="It is a gross misdemeanor for an officer to enter and search a private dwelling or residence without a search warrant.",
  points=["Read with the recognized exceptions in case law (consent with Ferrier warnings, exigency, emergency aid); the statute itself states only the warrant rule and penalty."],
  quote="It shall be unlawful for any police officer or other peace officer to enter and search any private dwelling house or place of residence without the authority of a search warrant",
  cards=[("What is the penalty in RCW 10.79.040 for searching a home without a warrant?","A gross misdemeanor for the officer.")]),
 dict(cite="9A.16.010", title="Justifiable force: definitions", group=G_JUST,
  summary="Criminal-code definitions: \"necessary\" means no reasonably effective alternative appeared to exist and the force was reasonable for the lawful purpose; \"deadly force\" is the intentional use of a firearm or other means reasonably likely to cause death or serious physical injury.",
  points=["Compare RCW 10.120.010's newer \"necessary\" definition, which adds proportionality."],
  quote="\"Deadly force\" means the intentional application of force through the use of firearms or any other means reasonably likely to cause death or serious physical injury.",
  cards=[("Define \"deadly force\" (RCW 9A.16.010).","The intentional application of force through firearms or any other means reasonably likely to cause death or serious physical injury.")]),
 dict(cite="9A.16.020", title="Use of force: when lawful", group=G_JUST,
  summary="Force is not unlawful when necessarily used by a public officer performing a legal duty (or someone assisting at the officer's direction), when used in self-defense or defense of others/property with no more force than necessary, and in several other listed situations.",
  points=["This is a criminal-law defense; RCW 10.120 sets the operational standard officers must follow."],
  quote="Whenever necessarily used by a public officer in the performance of a legal duty, or a person assisting the officer and acting under the officer's direction",
  cards=[("Under RCW 9A.16.020(1), when is an officer's force not unlawful?","When necessarily used by a public officer performing a legal duty (or a person assisting and acting under the officer's direction).")]),
 dict(cite="9A.16.040", title="Justifiable homicide / deadly force by peace officer", group=G_JUST,
  summary="Lists when an officer's deadly force is justifiable (e.g., to arrest a person reasonably believed to have committed a felony, to prevent certain escapes, to suppress an armed riot). The officer needs probable cause that the suspect poses a threat of serious physical harm to the officer or others, and should warn when feasible before using deadly force to prevent escape. Criminal liability is judged by an objective good-faith standard: would a similarly situated reasonable officer have believed deadly force was necessary.",
  points=["Threat of serious physical harm may include threatening with or displaying a weapon, or probable cause the suspect committed a crime involving serious physical harm.","Good faith (I-940, 2019 c 4) is objective, based on what the officer knew at the time.","Agencies may adopt stricter standards."],
  quote="a similarly situated reasonable officer would have believed that the use of deadly force was necessary to prevent death or serious physical harm to the officer or another individual",
  cards=[("What is the \"good faith\" standard in RCW 9A.16.040(4)?","An objective standard: considering all facts known to the officer at the time, would a similarly situated reasonable officer have believed deadly force was necessary to prevent death or serious physical harm to the officer or another."),
         ("Before deadly force to arrest under RCW 9A.16.040(1)(c), what must the officer have?","Probable cause that the suspect, if not apprehended, poses a threat of serious physical harm to the officer or others (e.g., threatens with or displays a weapon, or committed a crime involving serious physical harm). Warn if feasible before using it to prevent escape.")]),
 dict(cite="9A.16.050", title="Homicide by other person: when justifiable", group=G_JUST,
  summary="Homicide is justifiable in lawful defense of oneself, family or anyone present when there is reasonable ground to fear a felony or great personal injury and imminent danger, or in actually resisting an attempted felony on oneself or in one's dwelling.",
  points=["Applies to anyone, including officers acting outside 9A.16.040."],
  quote="there is imminent danger of such design being accomplished",
  cards=[("Two situations where homicide by a private person is justifiable (RCW 9A.16.050)?","(1) Lawful defense of self or others present with reasonable ground to fear a felony or great personal injury and imminent danger; (2) actual resistance of an attempted felony on the slayer or in the dwelling where they are.")]),
 dict(cite="10.93.070", title="General authority officer: statewide powers", group=G_AUTH,
  summary="A certified general authority Washington peace officer may enforce state traffic and criminal laws anywhere in the state with written consent of the local chief/sheriff, in an emergency threatening life or property, on a mutual-aid request or another officer's request, while transporting a prisoner, while executing an arrest or search warrant, or in fresh pursuit.",
  points=["This is how Valley SWAT members work in partner cities: mutual aid / request for assistance."],
  quote="In response to an emergency involving an immediate threat to human life or property",
  cards=[("Name the six circumstances in RCW 10.93.070 when you can enforce the law outside Federal Way.","Written consent of the local chief/sheriff; emergency with an immediate threat to life or property; mutual-aid agreement or request from an officer with authority; transporting a prisoner; executing an arrest or search warrant; fresh pursuit.")]),
 dict(cite="10.93.120", title="Fresh pursuit", group=G_AUTH,
  summary="An officer with arrest authority may pursue someone reasonably believed to have violated traffic or criminal law (or wanted on a warrant the officer holds) and arrest them anywhere in Washington. Fresh pursuit means pursuit without unreasonable delay, not necessarily immediate.",
  points=["Vehicle pursuits still must meet RCW 10.116.060."],
  quote="Fresh pursuit does not necessarily imply immediate pursuit, but pursuit without unreasonable delay.",
  cards=[("Does \"fresh pursuit\" (RCW 10.93.120) require immediate pursuit?","No. It means pursuit without unreasonable delay.")]),
 dict(cite="10.93.190", title="Duty to intervene and report", group=G_AUTH,
  summary="An identifiable on-duty officer who sees another officer use or try to use excessive force must intervene when in a position to do so, and must render aid to anyone injured by force at the earliest safe opportunity. Officers must report wrongdoing by another officer to a supervisor. No retaliation for good-faith intervening or reporting. Failures go to CJTC for possible decertification.",
  points=["Excessive force = force beyond what the law or the witnessing officer's agency policy allows.","Wrongdoing = conduct contrary to law or policy that isn't de minimis or technical."],
  quote="shall intervene when in a position to do so to end the use of excessive force or attempted use of excessive force",
  cards=[("What does RCW 10.93.190 require when you see another officer use excessive force?","Intervene when in a position to do so to end or prevent it, render aid to anyone injured at the earliest safe opportunity, and report the wrongdoing to a supervisor. Retaliation for good-faith intervention or reporting is prohibited."),
         ("How does RCW 10.93.190 define \"excessive force\"?","Force that exceeds the force permitted by law or by the policy of the witnessing officer's agency.")]),
 dict(cite="43.101.105", title="Decertification (CJTC)", group=G_CERT,
  summary="CJTC may deny, suspend or revoke certification, or require remedial training. It must deny or revoke for, among other things: certain convictions (felony, DV gross misdemeanor, sex offenses) in listed situations; termination after unlawful force causing death or serious injury; termination after failing to intervene or report excessive force; termination for dishonesty (perjury, false reports, hiding evidence); being prohibited from possessing weapons.",
  points=["Discretionary grounds in (3) cover a wider list of misconduct.","Duty-to-intervene failures connect directly to RCW 10.93.190(4)."],
  quote="Was in a position to intervene to end the excessive use of force and failed to do so",
  cards=[("Name three grounds for mandatory decertification under RCW 43.101.105(2).","E.g., termination after unlawful force that caused death or serious injury; termination after failing to intervene in or report excessive force; termination for knowingly false statements (perjury, false reports, hiding evidence); disqualifying convictions; being prohibited from possessing weapons.")]),
 dict(cite="9A.76.020", title="Obstructing a law enforcement officer", group=G_CRIME,
  summary="Willfully hindering, delaying or obstructing an officer in the discharge of official powers or duties. Gross misdemeanor.",
  points=["Covers general, limited and specially commissioned WA officers and federal peace officers."],
  quote="willfully hinders, delays, or obstructs any law enforcement officer in the discharge of his or her official powers or duties",
  cards=[("Elements and level of Obstructing (RCW 9A.76.020)?","Willfully hinders, delays or obstructs a law enforcement officer in the discharge of official powers or duties. Gross misdemeanor.")]),
 dict(cite="9A.76.023", title="Disarming a law enforcement officer", group=G_CRIME,
  summary="Knowingly taking a firearm or weapon from an officer, or depriving the officer of its use, with intent to interfere with the officer's duties, when the person knows or should know it's an officer. Class C felony; class B if the firearm is discharged.",
  points=[],
  quote="Disarming a law enforcement or corrections officer is a class B felony if the firearm involved is discharged when the person removes the firearm.",
  cards=[("Classification of Disarming a Law Enforcement Officer (RCW 9A.76.023)?","Class C felony; class B felony if the firearm is discharged when removed.")]),
 dict(cite="9A.76.040", title="Resisting arrest", group=G_CRIME,
  summary="Intentionally preventing or trying to prevent a peace officer from lawfully arresting you. Misdemeanor. The arrest must be lawful.",
  points=[],
  quote="intentionally prevents or attempts to prevent a peace officer from lawfully arresting him or her",
  cards=[("Resisting Arrest (RCW 9A.76.040): key element and level?","Intentionally preventing or attempting to prevent a peace officer from lawfully arresting the person. Misdemeanor.")]),
 dict(cite="9A.76.175", title="False or misleading statement to a public servant", group=G_CRIME,
  summary="Knowingly making a false or misleading material statement to a public servant. A material statement is one reasonably likely to be relied on by the public servant. Gross misdemeanor.",
  points=[],
  quote="A person who knowingly makes a false or misleading material statement to a public servant is guilty of a gross misdemeanor.",
  cards=[("What makes a statement \"material\" under RCW 9A.76.175?","A written or oral statement reasonably likely to be relied upon by a public servant in the discharge of official powers or duties.")]),
 dict(cite="9A.36.031", title="Assault in the third degree (incl. on an officer)", group=G_CRIME,
  summary="Third-degree assault includes assaulting someone to resist lawful process or lawful apprehension/detention, and assaulting a law enforcement officer or other law enforcement employee performing official duties. Class C felony.",
  points=["(1)(a): assault to prevent or resist lawful apprehension or detention.","(1)(g): assault on a law enforcement officer or agency employee performing official duties."],
  quote="Assaults a law enforcement officer or other employee of a law enforcement agency who was performing his or her official duties at the time of the assault",
  cards=[("Assaulting an on-duty officer in WA is what crime and class?","Assault in the third degree, RCW 9A.36.031(1)(g) (if not 1st or 2nd degree). Class C felony.")]),
 dict(cite="46.61.024", title="Attempting to elude a police vehicle", group=G_CRIME,
  summary="A driver who willfully fails to stop immediately and drives recklessly while trying to elude a pursuing police vehicle, after a visual or audible signal, commits a class C felony. The signaling officer must be in uniform and the vehicle must have lights and siren. Affirmative defense if a reasonable person wouldn't believe a police officer gave the signal and driving on was reasonable.",
  points=["License is revoked on conviction."],
  quote="The officer giving such a signal shall be in uniform and the vehicle shall be equipped with lights and sirens.",
  cards=[("Elements of Attempting to Elude (RCW 46.61.024)?","Driver willfully fails or refuses to stop immediately and drives recklessly while attempting to elude a pursuing police vehicle after a visual or audible signal to stop; the officer is in uniform and the vehicle has lights and siren. Class C felony.")]),
 dict(cite="71.05.153", title="Emergency detention for behavioral health", group=G_BH,
  summary="A peace officer may take a person into custody and immediately deliver them to a crisis stabilization unit, 23-hour crisis relief center, evaluation and treatment facility, withdrawal management facility, SUD program or hospital ER when the officer has reasonable cause to believe the person, because of a behavioral health disorder, presents an imminent likelihood of serious harm or is in imminent danger because of grave disability. The facility may hold them up to 12 hours (not counting time before medical clearance).",
  points=["ER exam by a mental health or SUD professional within 3 hours of arrival; DCR decision within 12 hours of notice.","Use of force for this purpose is a listed purpose in RCW 10.120.020(1)(d)."],
  quote="presents an imminent likelihood of serious harm or is in imminent danger because of being gravely disabled",
  cards=[("Standard for an officer-initiated emergency detention under RCW 71.05.153(2)?","Reasonable cause to believe the person, because of a behavioral health disorder, presents an imminent likelihood of serious harm or is in imminent danger because of being gravely disabled. Deliver immediately to an approved facility; it may hold up to 12 hours.")]),
]
